<?php
define('APP_INIT', true); define('IS_AJAX', true);
require_once __DIR__ . '/../../config/app.php'; require_once ROOT_PATH . '/includes/auth_check.php'; require_once ROOT_PATH . '/includes/permission_check.php'; require_once ROOT_PATH . '/includes/platform_check.php';
requirePlatformAdmin(); requirePermission('platform.manage');
if ($_SERVER['REQUEST_METHOD'] !== 'POST' || !verifyCsrfToken($_POST['csrf_token'] ?? '')) jsonResponse(false,'Invalid request.',[],403);
$tenant=(int)($_POST['tenant_id']??0);$plan=(int)($_POST['plan_id']??0);$status=$_POST['status']??'';$end=trim($_POST['ends_at']??'');
if(!$tenant||!$plan||!in_array($status,['trial','active','grace_period','expired','suspended','cancelled'],true))jsonResponse(false,'Invalid subscription values.',[],422);
$db=Database::getConnection();try{$db->beginTransaction();$t=$db->prepare('SELECT id FROM tenants WHERE id=:id FOR UPDATE');$t->execute([':id'=>$tenant]);if(!$t->fetchColumn())throw new Exception('Tenant not found.');$p=$db->prepare('SELECT id FROM subscription_plans WHERE id=:id');$p->execute([':id'=>$plan]);if(!$p->fetchColumn())throw new Exception('Plan not found.');$s=$db->prepare('INSERT INTO tenant_subscriptions(tenant_id,plan_id,status,starts_at,ends_at) VALUES(:tenant,:plan,:status,CURDATE(),:ends)');$s->execute([':tenant'=>$tenant,':plan'=>$plan,':status'=>$status,':ends'=>$end?:null]);$u=$db->prepare('UPDATE tenants SET status=:status WHERE id=:id');$u->execute([':status'=>$status,':id'=>$tenant]);logAudit('subscriptions','platform_update',(string)$tenant,null,['plan_id'=>$plan,'status'=>$status,'ends_at'=>$end]);$db->commit();jsonResponse(true,'Subscription updated.');}catch(Throwable $e){if($db->inTransaction())$db->rollBack();jsonResponse(false,'Subscription update failed: '.$e->getMessage(),[],422);}
